import{Q as e,St as t,at as n,it as r,jt as i,nt as a,o,ot as s,st as c,vt as l}from"./chunks/framework.DQt_9H6f.js";var u=JSON.parse(`{"title":"Programs: how they work","description":"","frontmatter":{},"headers":[],"relativePath":"guide/agent-architecture.md","filePath":"guide/agent-architecture.md"}`),d={name:`guide/agent-architecture.md`};function f(o,u,d,f,p,m){let h=t(`Mermaid`);return l(),r(`div`,null,[u[1]||=n(`<h1 id="programs-how-they-work" tabindex="-1">Programs: how they work <a class="header-anchor" href="#programs-how-they-work" aria-label="Permalink to “Programs: how they work”">​</a></h1><p>A program is a short script a plugin ships. A person or the assistant starts it by name; it starts helper agents, and it checks their work in code. That check is the reason it is a program and not a sentence of a prompt. For the list of programs, read <a href="./programs.html">The assistant and programs</a>.</p><p>A program is started in one of two ways:</p><ul><li>you ask the assistant, which proposes the run for you to approve;</li><li><code>texra run &lt;program&gt; --input …</code> in the terminal.</li></ul><h2 id="what-a-run-does" tabindex="-1">What a run does <a class="header-anchor" href="#what-a-run-does" aria-label="Permalink to “What a run does”">​</a></h2>`,5),(l(),a(e,null,{default:i(()=>[c(h,{id:`mermaid-24`,class:`mermaid`,graph:`sequenceDiagram%0A%20%20%20%20participant%20User%0A%20%20%20%20participant%20Assistant%0A%20%20%20%20participant%20Program%0A%20%20%20%20participant%20Helper%20agent%0A%0A%20%20%20%20User-%3E%3EAssistant%3A%20%22Referee%20section%202%20of%20main.tex%22%0A%20%20%20%20Assistant-%3E%3EUser%3A%20Proposes%20a%20program%20run%20(annotate%2C%20files%2C%20instruction)%0A%20%20%20%20User-%3E%3EAssistant%3A%20Approves%0A%20%20%20%20Assistant-%3E%3EProgram%3A%20program('annotate'%2C%20%7B%20prompt%2C%20inputFiles%20%7D)%0A%20%20%20%20loop%20each%20round%2C%20until%20the%20check%20passes%0A%20%20%20%20%20%20%20%20Program-%3E%3EHelper%20agent%3A%20The%20task%2C%20and%20what%20the%20last%20check%20reported%0A%20%20%20%20%20%20%20%20Helper%20agent--%3E%3EProgram%3A%20Edits%20the%20files%20in%20place%2C%20then%20replies%0A%20%20%20%20%20%20%20%20Program-%3E%3EProgram%3A%20Checks%20the%20files%20in%20code%0A%20%20%20%20end%0A%20%20%20%20Program--%3E%3EAssistant%3A%20The%20verdict%20and%20the%20helper's%20reply%0A`})]),fallback:i(()=>[...u[0]||=[s(` Loading... `,-1)]]),_:1})),u[2]||=n(`<ol><li><strong>A fresh helper each round.</strong> The program gives it a system prompt, the tools the job needs (file tools and the shell, and for Lean the Lean tools), your instruction and the file names. The helper reads and edits the files in your project directly. You can follow it in the <a href="./progress-board.html">Tasks view</a>.</li><li><strong>A coded check.</strong> <code>annotate</code> compares each file with what it was when the program started and accepts only added <code>\\criticize{}</code> comments. <code>prove</code> and <code>lean-simplify</code> ask Lean for errors, <code>sorry</code> and new axioms. <code>blueprint</code> runs <code>leanblueprint web</code> and <code>leanblueprint checkdecls</code>.</li><li><strong>Another round, or the answer.</strong> A failed check starts the next round with the check&#39;s report. The number of rounds is bounded, and the answer says plainly when the last round still failed.</li></ol><p><code>transcribe</code> and <code>lean-search</code> run one helper and answer with its reply.</p><p>Nothing is staged in run storage and there is no accept step: the files in your project are the result. Review them with your editor or <code>git diff</code>, and commit before a large change if you want an easy way back.</p><h2 id="anything-else-is-a-script" tabindex="-1">Anything else is a script <a class="header-anchor" href="#anything-else-is-a-script" aria-label="Permalink to “Anything else is a script”">​</a></h2><p>Several revision rounds with a critic between them, several candidates written in separate copies of the project, a compile after every change, a <code>latexdiff</code> against the original: the assistant writes these itself as a <a href="./multi-agent-workflows.html">script</a> over helper agents and the shell. Ask for the procedure you want in plain words.</p>`,5)])}var p=o(d,[[`render`,f]]);export{u as __pageData,p as default};